// ============================================================
// ROUTER: Parse Response + Override Rules (v3.0)
// ============================================================

const routerResponse = $json.text || $json.output || $json.content || '{}';
const context = $('Prepare for Router').first().json;

let parsed = { 
  category: 'INTERVIEW', 
  confidence: 0.5, 
  detected_language: 'ru' 
};

// Парсинг ответа LLM
try {
  const cleanJson = String(routerResponse)
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = { ...parsed, ...JSON.parse(jsonMatch[0]) };
  }
} catch (e) {
  console.log('Router parse error:', e.message);
  parsed.category = 'INTERVIEW';
}

// ======= ЖЁСТКИЕ ПРАВИЛА OVERRIDE (ПРИОРИТЕТ) =======

// ПРИОРИТЕТ 0 (ВЫСШИЙ): Callback для выбора языка
if (context.callback_data && context.callback_data.startsWith('lang_')) {
  parsed.category = 'LANGUAGE';
  parsed.confidence = 1.0;
}

// ПРИОРИТЕТ 1: История НЕ пуста → НИКОГДА НЕ GREETING
if (context.chat_history && context.chat_history.length > 0) {
  if (parsed.category === 'GREETING') {
    const text = (context.user_message || '').toLowerCase();
    // Может это FAQ?
    if (text.includes('зарплат') || text.includes('график') || 
        text.includes('условия') || text.includes('сколько') ||
        text.includes('вакансии') || text.includes('работа')) {
      parsed.category = 'FAQ';
    } else {
      parsed.category = 'INTERVIEW';
    }
  }
}

// ПРИОРИТЕТ 2: Есть имя в known_data → INTERVIEW (кроме FAQ/ESCALATION)
if (context.known_data && context.known_data.first_name) {
  if (parsed.category !== 'FAQ' && 
      parsed.category !== 'ESCALATION' && 
      parsed.category !== 'LANGUAGE') {
    parsed.category = 'INTERVIEW';
  }
}

// ПРИОРИТЕТ 3: Новый пользователь + приветствие
if (context.is_new_user && 
    (!context.chat_history || context.chat_history.length === 0)) {
  const text = (context.user_message || '').toLowerCase();
  if (text.includes('привет') || text.includes('здравст') || 
      text.includes('салам') || text.includes('hi') || 
      text.includes('hello') || text === '/start' || text === 'start') {
    parsed.category = 'GREETING';
    parsed.confidence = 1.0;
  }
}

// Логирование для отладки
console.log('🔍 ROUTER:', {
  message: context.user_message?.substring(0, 30),
  is_new_user: context.is_new_user,
  history_length: context.chat_history?.length || 0,
  has_name: !!context.known_data?.first_name,
  callback: context.callback_data,
  final_category: parsed.category
});

return {
  ...context,
  route_category: parsed.category,
  route_confidence: parsed.confidence || 0.8,
  detected_language: parsed.detected_language || context.language
};
